(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx1=x+wx1, sy1=y+wy1;
  const wx2=Math.sin(sx1*0.025-t*0.15)*8+Math.cos(sy1*0.03+t*0.2)*6;
  const wy2=Math.cos(sx1*0.02+t*0.18)*7+Math.sin(sy1*0.022-t*0.22)*5;
  const sx=sx1+wx2, sy=sy1+wy2;
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*40,0.085,1.8],
    [200+Math.sin(t*0.38+1)*90,220+Math.cos(t*0.48+3)*60,0.095,2.4],
    [300+Math.cos(t*0.42+4)*80,30+Math.sin(t*0.58+2)*55,0.075,2.0]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hrm+=Math.sin(d*f*0.5-t*sp*0.4+2.8)*0.5;
  }
  const act=aS/10,inh=iS/10,hr=hrm/10;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08-sy*0.06+t*1.6)+Math.cos(sx*0.07+sy*0.09-t*1.3))*0.5;
  const bg3=(Math.sin(sx*0.16+sy*0.12-t*2.2)+Math.cos(sx*0.14-sy*0.18+t*2.8))*0.25;
  const bg=bg1+bg2+bg3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.07+ang*2-t*2.0)+Math.cos(dist*0.06-ang*5+t*1.8))*0.2;
  const g1=Math.sin(sx*0.12)*Math.sin(sy*0.12);
  const g2=Math.sin((sx+sy)*0.085+t*0.5)*Math.sin((sx-sy)*0.085-t*0.3);
  const moire=(g1+g2)*0.3;
  const feed=act-inh*0.7+bg*0.3+sp1+sp2+hr*0.4;
  const rxn=Math.tanh(feed*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.tanh((Math.sin(sx*0.22+1)*Math.cos(sy*0.22-0.5)+Math.sin(sx*0.18+t*0.7)*0.4)*1.2)*0.15;
  const edge=Math.abs(rxn)>0.6?1.0+(Math.abs(rxn)-0.6)*0.5:1.0;
  const vign=1.0-Math.sqrt((x-240)**2+(y-120)**2)/320*0.25;
  const blend=rxn*0.55+cell*0.2+cell2*0.1+moire*0.15;
  const v=blend*0.5+0.5;
  const pal=[
    [4,8,38],[8,32,72],[14,68,105],[22,115,135],
    [60,168,155],[140,200,145],[215,210,85],
    [240,175,55],[230,115,65],[185,60,80],
    [110,30,70],[45,15,55],[4,8,38]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=(0.85+Math.sin(rxn*Math.PI)*0.15)*vign;
  const as=Math.sin(ang*2+t*0.3)*0.04;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+as*25)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f-as*18)*lum*edge)|0
  ];
}
